"use server";

import { Octokit } from "octokit";
import type { CommitData, CommitErrorKind, CommitInfo } from "./commitTypes";
import { getCachedCommitSearch, setCachedCommitSearch } from "./commitSearchCache";
import { githubProfileUrl } from "./githubUrls";
import { logger } from "./logger";
import { getUsernameValidationMessage, normalizeGitHubUsername } from "./username";

const octokit = new Octokit({
  auth: process.env.GITHUB_TOKEN,
});

const GITHUB_SEARCH_TIMEOUT_MS = 10_000;
const E2E_COMMIT_SEARCH_MOCKS_ENABLED = process.env.E2E_COMMIT_SEARCH_MOCKS === "1";
const E2E_SLOW_SEARCH_DELAY_MS = 750;
const E2E_REJECT_ONCE_USERNAME_PREFIX = "e2e-reject-once-";
const e2eRejectedUsernames = new Set<string>();
const EMPTY_COMMIT_SEARCH_MESSAGE =
  "No public commits found for this user (or indexing is delayed).";

function commitSearchError(error: string, errorKind: CommitErrorKind): CommitData {
  return { found: false, error, errorKind, commits: [] };
}

type GitHubErrorDetails = {
  message?: string;
  rateLimitRemaining?: number;
  rateLimitReset?: number;
  status?: unknown;
};

function parseNonNegativeInteger(value: unknown): number | undefined {
  if (typeof value === "number") {
    return Number.isSafeInteger(value) && value >= 0 ? value : undefined;
  }

  if (typeof value !== "string" || !/^\d+$/.test(value)) return undefined;

  const parsedValue = Number(value);
  return Number.isSafeInteger(parsedValue) ? parsedValue : undefined;
}

function getE2eCommitSearchResult(username: string): CommitData | null {
  if (!E2E_COMMIT_SEARCH_MOCKS_ENABLED) return null;

  // Keep browser tests deterministic without coupling them to GitHub search availability.
  const mockCommit: CommitInfo = {
    message: "Initial public commit\n\nAdd the first project files",
    date: "2020-01-02T03:04:05Z",
    html_url: "https://github.com/e2e-user/origin-repo/commit/abcdef123456",
    sha: "abcdef123456",
    repository: {
      name: "origin-repo",
      owner: "e2e-user",
      full_name: "e2e-user/origin-repo",
    },
    author: {
      login: username,
      avatar_url: "https://github.com/ghost.png",
      html_url: githubProfileUrl(username),
    },
  };

  if (
    username === "e2e-result" ||
    username === "e2e-slow-result" ||
    username.startsWith(E2E_REJECT_ONCE_USERNAME_PREFIX)
  ) {
    return {
      found: true,
      commits: [
        mockCommit,
        {
          ...mockCommit,
          message: "Follow-up commit",
          html_url: "https://github.com/e2e-user/next-repo/commit/bcdefa234567",
          sha: "bcdefa234567",
          repository: {
            name: "next-repo",
            owner: "e2e-user",
            full_name: "e2e-user/next-repo",
          },
        },
      ],
    };
  }

  if (username === "e2e-malformed-dates") {
    return {
      found: true,
      commits: [
        mockCommit,
        {
          ...mockCommit,
          message: "Commit with malformed date",
          date: "not-a-date",
          html_url: "https://github.com/e2e-user/next-repo/commit/bcdefa234567",
          sha: "bcdefa234567",
          repository: {
            name: "next-repo",
            owner: "e2e-user",
            full_name: "e2e-user/next-repo",
          },
        },
      ],
    };
  }

  switch (username) {
    case "e2e-empty":
      return commitSearchError(EMPTY_COMMIT_SEARCH_MESSAGE, "empty");
    case "e2e-rate-limit":
      return commitSearchError(
        "GitHub rate limit reached. Please try again in a few minutes.",
        "rate_limit",
      );
    case "e2e-unavailable":
      return commitSearchError(
        "GitHub is temporarily unavailable. Please try again soon.",
        "unavailable",
      );
    default:
      return null;
  }
}

function getGitHubErrorDetails(error: unknown): GitHubErrorDetails {
  if (typeof error !== "object" || error === null) {
    return {};
  }

  const status = "status" in error ? error.status : undefined;
  const message =
    "message" in error && typeof error.message === "string" ? error.message : undefined;
  const headers =
    "response" in error &&
    typeof error.response === "object" &&
    error.response !== null &&
    "headers" in error.response &&
    typeof error.response.headers === "object" &&
    error.response.headers !== null
      ? (error.response.headers as Record<string, unknown>)
      : undefined;

  return {
    message,
    rateLimitRemaining: parseNonNegativeInteger(headers?.["x-ratelimit-remaining"]),
    rateLimitReset: parseNonNegativeInteger(headers?.["x-ratelimit-reset"]),
    status,
  };
}

function isGitHubRateLimitError(errorDetails: GitHubErrorDetails) {
  if (errorDetails.status === 429) return true;
  if (errorDetails.rateLimitRemaining === 0) return true;

  return (
    errorDetails.status === 403 && /rate limit|too many requests/i.test(errorDetails.message ?? "")
  );
}

function isTimeoutError(error: unknown, errorDetails: GitHubErrorDetails) {
  if (
    typeof error === "object" &&
    error !== null &&
    "name" in error &&
    error.name === "AbortError"
  ) {
    return true;
  }

  return /aborted|timeout|timed out/i.test(errorDetails.message ?? "");
}

function isGitHubUnavailableError(errorDetails: GitHubErrorDetails) {
  return (
    typeof errorDetails.status === "number" &&
    errorDetails.status >= 500 &&
    errorDetails.status < 600
  );
}

function withTimeoutSignal<T>(callback: (signal: AbortSignal) => Promise<T>) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), GITHUB_SEARCH_TIMEOUT_MS);

  return Promise.resolve()
    .then(() => callback(controller.signal))
    .finally(() => clearTimeout(timeout));
}

function parseableDate(value: unknown): string | null {
  if (typeof value !== "string" || !value.trim()) return null;
  return Number.isNaN(Date.parse(value)) ? null : value;
}

function mapCommitItem(item: unknown, username: string): CommitInfo | null {
  if (typeof item !== "object" || item === null) return null;

  const candidate = item as {
    commit?: {
      message?: unknown;
      author?: { date?: unknown } | null;
      committer?: { date?: unknown } | null;
    };
    html_url?: unknown;
    sha?: unknown;
    repository?: {
      name?: unknown;
      full_name?: unknown;
      owner?: { login?: unknown } | null;
    };
    author?: {
      login?: unknown;
      avatar_url?: unknown;
      html_url?: unknown;
    } | null;
  };
  const message = candidate.commit?.message;
  const htmlUrl = candidate.html_url;
  const sha = candidate.sha;
  const repositoryName = candidate.repository?.name;
  const repositoryFullName = candidate.repository?.full_name;
  const repositoryOwner = candidate.repository?.owner?.login;

