test("retrying a partial result reaches the complete history", async ({ page }, testInfo) => {
  const partialUsername = `e2e-incomplete-once-${testInfo.workerIndex}-${Date.now().toString(36)}`;

  await searchForUsername(page, partialUsername);

  await expect(page.getByRole("heading", { name: "Earliest commit found so far" })).toBeVisible();

  await page.getByRole("button", { name: "Search again" }).click();

  // The fixture returns a complete result on the second call, so the banner clearing
  // proves the retry actually re-issued the search rather than re-rendering the same state.
  await expect(page.getByRole("heading", { name: "First public commit found" })).toBeVisible();
  await expect(
    page.locator('main [role="status"]').filter({ hasText: "GitHub returned a partial result" }),
  ).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Search again" })).toHaveCount(0);
  await expect(page.getByRole("link", { name: "Follow-up commit" })).toBeVisible();
});

