describe("SearchResults", () => {
  it("presents a complete result as the first public commit", () => {
    renderSearchResults();

    expect(screen.getByRole("heading", { level: 1 })).toHaveTextContent(
      "First public commit found",
    );
    expect(screen.queryByRole("button", { name: "Search again" })).not.toBeInTheDocument();
  });

  it("does not claim a partial result is the first commit", () => {
    renderSearchResults({ isIncomplete: true });

    expect(screen.getByRole("heading", { level: 1 })).not.toHaveTextContent(
      "First public commit found",
    );
    expect(screen.getByRole("status")).toHaveTextContent(/partial result/i);
    expect(screen.getByRole("status")).toHaveTextContent(/earlier commit/i);
  });

  it("offers a retry for the same username when the search was incomplete", async () => {
    const user = userEvent.setup();
    const { onRetry } = renderSearchResults({ isIncomplete: true });

    await user.click(screen.getByRole("button", { name: "Search again" }));

    expect(onRetry).toHaveBeenCalledWith("octo");
  });

  it("disables the retry while another search is pending", () => {
    renderSearchResults({ isIncomplete: true, isPending: true });

    expect(screen.getByRole("button", { name: "Search again" })).toBeDisabled();
  });

