import { useEffect, useRef } from "react";
import { GoCopy } from "react-icons/go";
import FirstCommitDisplay from "@/components/FirstCommitDisplay";
import { githubRepositoryUrl } from "../githubUrls";
import type { CommitInfo } from "../commitTypes";

const PARTIAL_RESULT_HEADING_ID = "partial-result-heading";
const PARTIAL_RESULT_DESCRIPTION_ID = "partial-result-description";

type SearchResultsProps = {
  commits: CommitInfo[];
  lastSearchedUsername: string;
  shareStatus: string;
  isIncomplete: boolean;
  isPending: boolean;
  retryError: string;
  onCopy: () => void;
  onRetry: (username: string) => void;
};

export default function SearchResults({
  commits,
  lastSearchedUsername,
  shareStatus,
  isIncomplete,
  isPending,
  retryError,
  onCopy,
  onRetry,
}: SearchResultsProps) {
  const resultHeadingRef = useRef<HTMLHeadingElement>(null);
  const firstCommit = commits[0];

  useEffect(() => {
    if (firstCommit) resultHeadingRef.current?.focus();
  }, [firstCommit, lastSearchedUsername]);

  if (!firstCommit) return null;

  const uniqueRepositoryCount = new Set(commits.map((commit) => commit.repository.full_name)).size;
  const isRetryDisabled = isPending || !lastSearchedUsername;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 w-full flex flex-col items-center pb-12 pt-8">
      <div className="mb-6 w-full max-w-2xl text-left">
        <h1
          ref={resultHeadingRef}
          tabIndex={-1}
          aria-describedby={isIncomplete ? PARTIAL_RESULT_DESCRIPTION_ID : undefined}
          className="rounded-sm text-2xl font-bold text-[var(--github-gray-dark)] focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2"
        >
          {isIncomplete ? "Earliest public commit found so far" : "First public commit found"}
        </h1>
        <p className="mt-2 text-sm text-[var(--github-gray-dark)]">
          Earliest indexed public commit for @{lastSearchedUsername} appears in{" "}
          <a
            href={githubRepositoryUrl(firstCommit.repository.full_name)}
            className="font-semibold text-[var(--github-blue)] hover:underline"
          >
            {firstCommit.repository.full_name}
          </a>
          {uniqueRepositoryCount > 1
            ? `, with nearby early commits across ${uniqueRepositoryCount} repositories.`
            : "."}
        </p>
        {isIncomplete ? (
          // The caveat is announced through the heading's description rather than a live
          // region: the block mounts with its content already inside it, which screen
          // readers often skip, while the heading reliably takes focus when results arrive.
          <section
            aria-labelledby={PARTIAL_RESULT_HEADING_ID}
            className="mt-3 rounded-md border border-amber-300 bg-amber-50 p-5 text-amber-900 shadow-sm"
          >
            <h2 id={PARTIAL_RESULT_HEADING_ID} className="text-base font-semibold">
              GitHub returned a partial result
            </h2>
            <p id={PARTIAL_RESULT_DESCRIPTION_ID} className="mt-2 text-sm">
              The search timed out before scanning every commit, so an earlier commit may be
              missing. Searching again often reaches the full history.
            </p>
            {retryError ? (
              // Added after mount in response to a user action, so a live region announces
              // reliably here in a way the surrounding static caveat would not.
              <p role="alert" className="mt-2 text-sm font-semibold">
                That retry did not finish: {retryError} The commits below are still the earlier
                partial result.
              </p>
            ) : null}
            <button
              type="button"
              onClick={() => {
                if (isPending) return;
                onRetry(lastSearchedUsername);
              }}
              // aria-disabled rather than disabled: a disabled control loses focus the moment
              // it is pressed, which would strand a keyboard user mid-action. The retry in
              // SearchErrorState still uses disabled; it has no equivalent pending state on
              // screen, so it is a deliberate exception rather than a second convention.
              aria-disabled={isPending}
              className="mt-4 inline-flex items-center justify-center rounded-md border border-amber-700 bg-white px-3 py-2 text-sm font-semibold text-amber-900 hover:bg-amber-100 focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2 focus:ring-offset-amber-50 aria-disabled:cursor-not-allowed aria-disabled:border-amber-600 aria-disabled:bg-amber-50 aria-disabled:hover:bg-amber-50"
            >
              {isPending ? "Searching again..." : "Search again"}
            </button>
          </section>
        ) : (
          <p className="mt-2 text-sm text-[var(--github-gray-text)]">
            GitHub search may miss older commits when indexing is incomplete, delayed, or author
            metadata changed.
          </p>
        )}
        <div className="mt-4 flex flex-wrap items-center gap-2">
          <button
            type="button"
            onClick={onCopy}
            className="inline-flex items-center justify-center gap-1.5 rounded-md border border-[var(--github-border)] bg-white px-3 py-2 text-sm font-semibold text-[var(--github-gray-dark)] shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2"
          >
            <GoCopy aria-hidden="true" />
            Copy result
          </button>
          {shareStatus ? (
            <span
              role="status"
              aria-live="polite"
              className="text-sm font-medium text-[var(--github-gray-text)]"
            >
              {shareStatus}
            </span>
          ) : null}
        </div>
      </div>

      <div className="relative w-full max-w-2xl">
        <div className="absolute bottom-0 left-8 top-10 -z-10 hidden w-0.5 bg-[var(--github-border)] sm:block" />

        <div className="flex flex-col gap-0">
          <div className="mb-8 flex gap-4">
            <div className="mt-12 hidden flex-col items-center sm:flex">
              <div className="h-4 w-4 rounded-sm border border-[var(--github-green-hover)] bg-[var(--github-green)] shadow-sm" />
            </div>
            <div className="min-w-0 flex-1">
              <FirstCommitDisplay data={firstCommit} isMain />
            </div>
          </div>

