import { afterEach, describe, expect, it, vi } from "vitest";
import { getCommits } from "../actions";
import type { CommitData, CommitInfo } from "../commitTypes";
import { trackAppEvent } from "./analytics";
import { saveStoredRecentSearches } from "./recentSearches";
import { runCommitSearch } from "./searchExecution";
import { updateSharedSearchUrl } from "./sharedSearch";

vi.mock("../actions", () => ({ getCommits: vi.fn() }));
vi.mock("./analytics", () => ({ trackAppEvent: vi.fn() }));
vi.mock("./recentSearches", () => ({ saveStoredRecentSearches: vi.fn() }));
vi.mock("./sharedSearch", () => ({ updateSharedSearchUrl: vi.fn() }));

const commit: CommitInfo = {
  message: "Initial commit",
  date: "2020-01-02T03:04:05Z",
  html_url: "https://github.com/octocat/repo/commit/abc123",
  sha: "abc123",
  repository: { name: "repo", owner: "octocat", full_name: "octocat/repo" },
  author: {
    login: "octocat",
    avatar_url: "https://github.com/ghost.png",
    html_url: "https://github.com/octocat",
  },
};

const foundResult: CommitData = { found: true, commits: [commit] };

function createDeferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((resolvePromise) => {
    resolve = resolvePromise;
  });

  return { promise, resolve };
}

// The real `startTransition` runs its callback in a React transition; the test
// double runs it immediately and exposes the resulting promise so assertions
// can await the async search work.
function createHandlers() {
  let pending: Promise<unknown> | undefined;
  const handlers = {
    isLatestSearch: vi.fn(() => true),
    startTransition: vi.fn((callback: () => unknown) => {
      pending = Promise.resolve(callback());
    }),
    setLastSearchedUsername: vi.fn(),
    setShareStatus: vi.fn(),
    applyResult: vi.fn(),
    setRecentSearches: vi.fn(),
  };
  return { handlers, settle: () => pending };
}

afterEach(() => {
  vi.clearAllMocks();
});

describe("runCommitSearch", () => {
  it("ignores blank usernames", () => {
    const { handlers } = createHandlers();
    runCommitSearch("   ", {}, handlers);

    expect(handlers.startTransition).not.toHaveBeenCalled();
    expect(trackAppEvent).not.toHaveBeenCalled();
  });

  it("ignores invalid usernames", () => {
    const { handlers } = createHandlers();
    runCommitSearch("bad_name", {}, handlers);

    expect(handlers.startTransition).not.toHaveBeenCalled();
  });

  it("updates the shared URL and tracks a user-sourced search", async () => {
    vi.mocked(getCommits).mockResolvedValue(foundResult);
    const { handlers, settle } = createHandlers();

    runCommitSearch("octocat", { updateUrl: true }, handlers);
    await settle();

    expect(updateSharedSearchUrl).toHaveBeenCalledWith("octocat");
    expect(handlers.setLastSearchedUsername).toHaveBeenCalledWith("octocat");
    expect(handlers.setShareStatus).toHaveBeenCalledWith("");
    expect(handlers.applyResult).toHaveBeenCalledWith(foundResult);
    expect(trackAppEvent).toHaveBeenCalledWith("search_submitted", { source: "user" });
    expect(trackAppEvent).toHaveBeenCalledWith("search_completed", {
      found: true,
      error_kind: "none",
      commit_count: 1,
      incomplete: false,
    });
  });

  it("does not touch the URL for shared-link searches", async () => {
    vi.mocked(getCommits).mockResolvedValue(foundResult);
    const { handlers, settle } = createHandlers();

    runCommitSearch("octocat", {}, handlers);
    await settle();

    expect(updateSharedSearchUrl).not.toHaveBeenCalled();
    expect(trackAppEvent).toHaveBeenCalledWith("search_submitted", { source: "shared_url" });
  });

  it("persists successful searches, de-duplicating case-insensitively", async () => {
    vi.mocked(getCommits).mockResolvedValue(foundResult);
    const { handlers, settle } = createHandlers();

    runCommitSearch("octocat", {}, handlers);
    await settle();

    expect(handlers.setRecentSearches).toHaveBeenCalledTimes(1);
    const updater = handlers.setRecentSearches.mock.calls[0][0] as (prev: string[]) => string[];
    const next = updater(["OCTOCAT", "torvalds"]);

    expect(next).toEqual(["octocat", "torvalds"]);
    expect(saveStoredRecentSearches).toHaveBeenCalledWith(["octocat", "torvalds"]);
  });

  it("does not record recent searches for unsuccessful results", async () => {
    vi.mocked(getCommits).mockResolvedValue({ found: false, errorKind: "empty", commits: [] });
    const { handlers, settle } = createHandlers();

    runCommitSearch("octocat", {}, handlers);
    await settle();

    expect(handlers.setRecentSearches).not.toHaveBeenCalled();
    expect(trackAppEvent).toHaveBeenCalledWith("search_completed", {
      found: false,
      error_kind: "empty",
      commit_count: 0,
      incomplete: false,
    });
  });

  it("normalizes unexpected Server Action rejections as retryable unknown errors", async () => {
    vi.mocked(getCommits).mockRejectedValue(
      new Error("Sensitive upstream detail: q=author:octocat&token=secret"),
    );
    const { handlers, settle } = createHandlers();

    runCommitSearch("octocat", {}, handlers);

    await expect(settle()).resolves.toBeUndefined();
    expect(handlers.applyResult).toHaveBeenCalledWith({
      found: false,
      error: "GitHub commit search failed. Please try again.",
      errorKind: "unknown",
      commits: [],
    });
    expect(handlers.setRecentSearches).not.toHaveBeenCalled();
    expect(trackAppEvent).toHaveBeenLastCalledWith("search_completed", {
      found: false,
      error_kind: "unknown",
      commit_count: 0,
      incomplete: false,
    });
    expect(JSON.stringify(handlers.applyResult.mock.calls)).not.toContain("octocat");
    expect(JSON.stringify(handlers.applyResult.mock.calls)).not.toContain("secret");
  });

  it("ignores an earlier search that resolves after the latest request", async () => {
    const staleSearch = createDeferred<CommitData>();
    const latestSearch = createDeferred<CommitData>();
    const staleResult: CommitData = {
      found: true,
      commits: [{ ...commit, message: "Stale search result" }],
    };
    const latestResult: CommitData = {
      found: true,
      commits: [{ ...commit, message: "Latest search result" }],
    };
    vi.mocked(getCommits).mockImplementation((username) =>
      username === "octocat" ? staleSearch.promise : latestSearch.promise,
    );
    const pendingSearches: Promise<unknown>[] = [];
    const handlers = {
      startTransition: vi.fn((callback: () => unknown) => {
        pendingSearches.push(Promise.resolve(callback()));
      }),
      setLastSearchedUsername: vi.fn(),
      setShareStatus: vi.fn(),
      applyResult: vi.fn(),
      setRecentSearches: vi.fn(),
    };
    let latestSearchId = 0;
    const startSearch = (username: string) => {
      const searchId = ++latestSearchId;
      runCommitSearch(
        username,
        {},
        {
          ...handlers,
          isLatestSearch: () => searchId === latestSearchId,
        },
      );
    };

    startSearch("octocat");
    startSearch("torvalds");
    latestSearch.resolve(latestResult);
    await pendingSearches[1];
    staleSearch.resolve(staleResult);
    await pendingSearches[0];

    expect(handlers.setLastSearchedUsername).toHaveBeenLastCalledWith("torvalds");
    expect(handlers.applyResult).toHaveBeenCalledOnce();
    expect(handlers.applyResult).toHaveBeenCalledWith(latestResult);
    expect(handlers.setRecentSearches).toHaveBeenCalledOnce();
    expect(trackAppEvent).toHaveBeenCalledTimes(3);
    expect(trackAppEvent).toHaveBeenLastCalledWith("search_completed", {
      found: true,
      error_kind: "none",
      commit_count: 1,
      incomplete: false,
    });
  });
});

"use client";

import type { FormEvent } from "react";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import { FaGithub } from "react-icons/fa";
import { trackAppEvent } from "./home/analytics";
import { EXAMPLE_USERNAMES } from "./home/constants";
import SearchErrorState from "./home/SearchErrorState";
import SearchForm from "./home/SearchForm";
import SearchResults from "./home/SearchResults";
import SearchShortcutSection from "./home/SearchShortcutSection";
import { useCommitSearch } from "./home/useCommitSearch";
import {
  buildResultShareText,
  clearSharedSearchUrl,
  getInitialSharedUsername,
} from "./home/sharedSearch";
import { getUsernameValidationMessage } from "./username";
const APP_RELEASE = process.env.NEXT_PUBLIC_APP_RELEASE ?? "local";
const APP_RELEASE_URL = process.env.NEXT_PUBLIC_APP_RELEASE_URL ?? "";

export default function Home() {
  const [username, setUsername] = useState("");
  const searchInputRef = useRef<HTMLInputElement>(null);
  const {
    result,
    setResult,
    lastSearchedUsername,
    setLastSearchedUsername,
    recentSearches,
    clearRecentSearches,
    shareStatus,
    setShareStatus,
    retryError,
    isPending,
    runSearch,
    cancelPendingSearch,
  } = useCommitSearch();

  const focusSearchInput = () => {
    requestAnimationFrame(() => searchInputRef.current?.focus());
  };

  useEffect(() => {
    if (!result?.found) {
      searchInputRef.current?.focus();
    }
  }, [result?.found]);

  useEffect(() => {
    const sharedUsername = getInitialSharedUsername();
    if (!sharedUsername) return;

    const autoSearch = window.setTimeout(() => {
      setUsername(sharedUsername);
      runSearch(sharedUsername);
    }, 0);

    return () => window.clearTimeout(autoSearch);
  }, [runSearch]);

  const handleClearRecentSearches = () => {
    clearRecentSearches();
    focusSearchInput();
  };

  const handleSearch = (event: FormEvent) => {
    event.preventDefault();
    runSearch(username, { updateUrl: true });
  };

  const resetSearch = () => {
    cancelPendingSearch();
    setResult(null);
    setShareStatus("");
    clearSharedSearchUrl();
    focusSearchInput();
  };

  const startNewSearch = () => {
    cancelPendingSearch();
    setResult(null);
    setUsername("");
    setLastSearchedUsername("");
    setShareStatus("");
    clearSharedSearchUrl();
    focusSearchInput();
  };

  const handleShortcutSearch = (shortcutUsername: string) => {
    setUsername(shortcutUsername);
    runSearch(shortcutUsername, { updateUrl: true });
  };

  const usernameValidationMessage = getUsernameValidationMessage(username);
  const canSearch = Boolean(username.trim()) && !usernameValidationMessage && !isPending;

  const copyResult = async () => {
    if (!result?.found || !navigator.clipboard) {
      setShareStatus("Copy is not available in this browser.");
      trackAppEvent("result_copy_unavailable");
      return;
    }

    try {
      await navigator.clipboard.writeText(buildResultShareText(lastSearchedUsername, result));
      setShareStatus("Result copied.");
      trackAppEvent("result_copied");
    } catch {
      // Clipboard writes can fail on permissions or unsupported browsers;
      // surface a fallback message instead of letting the rejection bubble up.
      setShareStatus("Could not copy result. Use the commit link instead.");
      trackAppEvent("result_copy_failed");
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[var(--background)] font-sans">
      {/* Header */}
      <header
        aria-label="Site header"
        className="sticky top-0 z-50 py-3 px-6 border-b border-[var(--github-border)] bg-[var(--github-gray-light)] flex items-center justify-between backdrop-blur-sm bg-white/80"
      >
        <div className="flex items-center gap-2 font-bold text-xl text-[var(--github-gray-dark)]">
          <FaGithub className="text-3xl" />
          <span>My First Commit</span>
        </div>
        {result?.found ? (
          <button
            onClick={startNewSearch}
            disabled={isPending}
            className="rounded-md border border-[var(--github-border)] bg-white px-3 py-1.5 text-xs font-semibold text-[var(--github-gray-dark)] shadow-sm transition-colors hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Search another user
          </button>
        ) : null}
      </header>

      {/* Main */}
      <main
        aria-label="Commit search"
        className="mx-auto flex w-full max-w-4xl flex-1 flex-col items-center p-4"
      >
        {!result?.found ? (
          <div
            className={`mb-8 mt-20 text-center transition-all duration-500 ${isPending ? "opacity-50" : "opacity-100"}`}
          >
            <h1 className="mb-4 text-3xl font-extrabold tracking-tight text-[var(--github-gray-dark)] sm:text-5xl">
              Discover your origin.
            </h1>
            <p className="text-lg text-[var(--github-gray-text)]">
              Enter your GitHub username to find your very first public commit.
            </p>
          </div>
        ) : null}

        {!result?.found ? (
          <SearchForm
            username={username}
            validationMessage={usernameValidationMessage}
            canSearch={canSearch}
            isPending={isPending}
            searchInputRef={searchInputRef}
            onSubmit={handleSearch}
            onUsernameChange={setUsername}
          />
        ) : null}

        {!result?.found && recentSearches.length > 0 ? (
          <SearchShortcutSection
            title="Recent searches"
            usernames={recentSearches}
            isPending={isPending}
            onSearch={handleShortcutSearch}
            getButtonLabel={(recentUsername) => `@${recentUsername}`}
