import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import type { CommitData } from "../commitTypes";
import { clearStoredRecentSearches, getStoredRecentSearches } from "./recentSearches";
import { getResultMessage } from "./resultMessages";
import { runCommitSearch } from "./searchExecution";

type RunSearchOptions = { updateUrl?: boolean; keepResultOnFailure?: boolean };

/**
 * Owns the commit-search result lifecycle (result, last-searched username,
 * recent searches, share status, and the pending transition) so the page
 * component can trigger a search with a single `runSearch` call instead of
 * threading state setters through every handler.
 */
export function useCommitSearch() {
  const [result, setResult] = useState<CommitData | null>(null);
  const [lastSearchedUsername, setLastSearchedUsername] = useState("");
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [shareStatus, setShareStatus] = useState("");
  const [retryError, setRetryError] = useState("");
  const [isPending, startTransition] = useTransition();
  const latestSearchIdRef = useRef(0);
  const resultRef = useRef<CommitData | null>(null);

  useEffect(() => {
    resultRef.current = result;
  }, [result]);

  useEffect(() => {
    const loadRecentSearches = window.setTimeout(() => {
      setRecentSearches(getStoredRecentSearches());
    }, 0);

    return () => window.clearTimeout(loadRecentSearches);
  }, []);

  const runSearch = useCallback((searchUsername: string, options: RunSearchOptions = {}) => {
    const searchId = ++latestSearchIdRef.current;
    setRetryError("");

    runCommitSearch(searchUsername, options, {
      isLatestSearch: () => searchId === latestSearchIdRef.current,
      startTransition,
      setLastSearchedUsername,
      setShareStatus,
      applyResult: (data) => {
        // A retry launched from the results view must not destroy the result the visitor is
        // reading: a shared rate limit or timeout would otherwise replace their commits with
        // an error screen as a punishment for taking the retry the UI offered.
        if (options.keepResultOnFailure && !data.found && resultRef.current?.found) {
          setRetryError(getResultMessage(data).description);
          return;
        }

        setResult(data);
      },
      setRecentSearches,
    });
  }, []);

  // Reset controls clear the result but cannot clear an in-flight request, so without this a
  // slow search resolving after a reset would remount results over the page the visitor moved to.
  const cancelPendingSearch = useCallback(() => {
    latestSearchIdRef.current += 1;
    setRetryError("");
  }, []);

  const clearRecentSearches = useCallback(() => {
    setRecentSearches([]);
    clearStoredRecentSearches();
  }, []);

  return {
    result,
    setResult,
    lastSearchedUsername,
    setLastSearchedUsername,
    recentSearches,
    clearRecentSearches,
    shareStatus,
    setShareStatus,
    retryError,
    isPending,
    runSearch,
    cancelPendingSearch,
  };
}

